68:#   --out F            append the row to F (flock when available); default stdout
103:    --out)            OUT="${2:-}"; shift 2 ;;
204:  jq -c '.' "$GRADE" > "$WORK/grade.json" || usage "grade file does not parse: $GRADE"
209:  jq -c '.' "$MANIFEST" > "$WORK/manifest.json" || usage "manifest does not parse: $MANIFEST"
212:jq -c '.' "$PIPE" > "$WORK/pipe.json" || usage "meta/pipeline.json does not parse"
239:  if [[ -f "$f" ]] && jq -e 'type == "object"' "$f" >/dev/null 2>&1; then jq -c '.' "$f"; else echo null; fi
411:    { flock -x 9; printf '%s\n' "$ROW" >> "$OUT"; } 9>>"$OUT.lock"
413:    printf '%s\n' "$ROW" >> "$OUT"
48:@test "RAB-1 --dry-run: plan shape (arms x applicable tasks x trials), one refused line per inapplicable pair, trial-major order, MANIFEST.json with every §3.4 field, no run dir and no pipeline call" {
96:@test "RAB-2 the shuffle is a seeded Fisher-Yates per trial block: reproducible for a seed (and equal to random.Random(seed).shuffle), different for another seed" {
121:@test "RAB-3 hard gate (DEC-0435): a non-smoke batch without MANIFEST.sha256, without the self-check log, or with a task lacking REVIEW.md is refused (exit 2, REFUSED.txt only); with all three their hashes land in MANIFEST.json gate" {
161:@test "RAB-4 --smoke skips the hard gate but still requires the freeze; smoke rows go to the batch's rows.jsonl, graded with --tasks-dir smoke" {
189:@test "RAB-5 dispatch and rows: completed rows validate; agent_error is never retried (not even when the agent writes 'rate limit'); a transport failure is retried once (attempts 2, retry_reason, one row) and twice is transport_error; a cap failure charges run_cap; a grade exit 2 rows infrastructure_error" {
226:@test "RAB-6 took-effect pause (DEC-0418): a run whose evidence fails rows infrastructure_error and pauses the arm, later trials of that arm do not launch; --resume --clear-arm continues them" {
257:@test "RAB-7 drift guard (DEC-0407): an init claude_code_version other than MANIFEST cli_version fails the batch (state failed, drift populated, nothing more launches); a foreign model id does too" {
278:@test "RAB-8 watchdog (DEC-0429): a pipeline that hangs past the deadline (with a running record, or with none) is SIGTERMed and rowed interrupted" {
292:@test "RAB-9 --max-usd: USD 5 per trial under max 12 launches two (0+7 hint, 5+5) and cuts the third (10+5 > 12) with cuts[] populated; exit 1" {
305:@test "RAB-10 --resume: an interrupted batch (STATUS mid-plan, two rows, one stale run dir) resumes without duplicate run_ids and finishes" {
336:@test "RAB-11 --detach re-execs in a new session, prints the batch dir and pid, and the batch completes in the background" {
347:@test "RAB-12 usage and pre-flight refusals exit 2: unknown or absent arm, smoke- batch without --smoke, resume without a batch, a missing image (REFUSED.txt), a source tree not at the commit" {
369:@test "RAB-13 a signalled driver marks the batch partial, terminates its running pipelines by process group, and --resume reruns the unrowed trial into a fresh run dir" {
398:@test "RAB-14 is_pipeline_transport_failure: only an agent_error whose failing phase shows a CLI transport signature (stderr, api_error_status, an is_error result) counts; the agent's own text, a non-failing phase and a completed run never do" {
425:@test "RAB-15 a start is refused while a process group recorded by an earlier (SIGKILLed) driver still runs" {
440:@test "RAB-16 an extra model beside the requested one (a WebFetch summariser, DEC-0545) is not drift: the trial completes and grades, the trial log names it, STATUS.json extra_models counts it, the row is not degraded" {
459:@test "RAB-17 --clear-drift: a drift recorded under the old rule on an extra-model run is re-read clean (drift null, drift_cleared[], the rest of the plan runs); a real substitution is still a drift (exit 2, STATUS.json unchanged); --clear-drift needs --resume" {
502:@test "RAB-18 --rerow: an infrastructure_error row left by the old drift rule on an extra-model run is rowed again (one row, completed, rerowed[], spend counts it once, no pipeline call); an unknown id, another batch's id, a duplicated row, an interrupted row and a rerow without --resume are refused with the rows file byte-identical" {
559:@test "RAB-19 --rerun-status transport_error (DEC-0553): a finished batch's two transport rows are launched again into -r3 dirs and replaced in place (one row per run_id, rerun[], no assumed charge left, spent = rows + ledger); --rerun of a completed row, --rerun-status completed, --rerun without --resume and an id given to both --rerun and --rerow are refused with the rows file byte-identical" {
618:@test "RAB-19b --rerow and --rerun in one resume: an infrastructure_error row left by the old drift rule is rowed again and a transport row is launched again; each lands in its own STATUS array" {
646:@test "RAB-20 outage breaker (DEC-0554): three consecutive transport_error collections stop launches (partial, STATUS.outage, the message in run.log); a non-transport collection resets the count; --resume --rerun-status transport_error completes the batch and moves outage to outage_history; LOA_ABLATION_OUTAGE_BREAKER=0 runs to the end" {

